uniform float amzp_radius;
uniform float amzp_exposure;
uniform float amzp_softClipKnee;
uniform float amzp_spread;
uniform float amzp_glowTail;
uniform float amzp_glowOcclusion;
uniform float amzp_threshold;
uniform float amzp_thresholdSmooth;
uniform float amzp_thresholdGamma;
uniform float amzp_blendMode;
layout(color) uniform half4 amzp_tint;
uniform float amzp_tintStrength;
uniform float amzp_sshadow;
uniform float amzp_alphaa;
