uniform float amzp_shadowOnly;
uniform float amzp_quality;
uniform float amzp_glowOnly;
uniform float amzp_ditherAmount;








    const float PI = 3.14159265358979323846;


    float3 srgbToLinear(float3 srgb){
      float3 cut = step(float3(0.04045), srgb);
      float3 low = srgb / 12.92;
      float3 high = pow((srgb + 0.055) / 1.055, float3(2.4));
      return mix(low, high, cut);
    }
    float3 linearToSrgb(float3 lin){
      float3 cut = step(float3(0.0031308), lin);
      float3 low = lin * 12.92;
      float3 high = 1.055 * pow(lin, float3(1.0/2.4)) - 0.055;
      return mix(low, high, cut);
    }


    float4 blurInternal(int tex, float2 texOffset, float2 st, float numBlurPixelsPerSide)
    {
      if(numBlurPixelsPerSide <= 0.0) return amzTexture(tex, st);

       float3 incrementalGaussian;
      float adjSigma = numBlurPixelsPerSide / 2.14596602; 
      incrementalGaussian.x = 1.0 / (sqrt(2.0 * PI) * max(adjSigma, 1e-4));
      incrementalGaussian.y = exp(-0.5 / (max(adjSigma, 1e-4) * max(adjSigma, 1e-4)));
      incrementalGaussian.z = incrementalGaussian.y * incrementalGaussian.y;

      float4 avgValue = amzTexture(tex, st).rgba * incrementalGaussian.x;
       float coefficientSum = incrementalGaussian.x;


      for (float i = 1.0; i <= 256.0; i += 2.0) {
        if (i > numBlurPixelsPerSide) break;
        float offset0 = i;
        float offset1 = i + 1.0;

        incrementalGaussian.xy *= incrementalGaussian.yz;
        coefficientSum += (2.0 * incrementalGaussian.x);
        float weight0 = incrementalGaussian.x;
        incrementalGaussian.xy *= incrementalGaussian.yz;
        coefficientSum += (2.0 * incrementalGaussian.x);
        float weight1 = incrementalGaussian.x;
        float weightL = weight0 + weight1;
        float offsetL = (offset0*weight0 + offset1*weight1) / max(weightL, 1e-6);
        float2 stL = st - offsetL * texOffset;
        float2 stR = st + offsetL * texOffset;
        avgValue += amzTexture(tex, stL) * weightL;
        avgValue += amzTexture(tex, stR) * weightL;
      }
      return avgValue / max(coefficientSum, 1e-6);
    }

    float tapsForQualityF(float q){
      return (q < 1.5) ? 8.0 : ((q < 2.5) ? 14.0 : 20.0);
    }


    float luminance(float3 c){ return dot(c, float3(0.2126, 0.7152, 0.0722)); }

    void amzRender(){
      float taps = tapsForQualityF(float(int(amzp_quality)));


      float r1 = amzp_radius;
      float r2 = amzp_radius * (1.8 + amzp_spread);
      float r3 = amzp_radius * (3.5 + 2.0*amzp_spread);


      float2 uv = amzScreenNorm();

      if (amzPass == 0) {

        float4 src4 = amzTexture(0, uv);
        float3 srcRGB = src4.rgb;

        float lum = luminance(srgbToLinear(srcRGB));
        lum = pow(max(lum, 0.0), amzp_thresholdGamma);
        float t = (amzp_thresholdSmooth <= 0.0) ? step(amzp_threshold, lum)
                                          : smoothstep(amzp_threshold - amzp_thresholdSmooth, amzp_threshold + amzp_thresholdSmooth, lum);

        float3 glowSrc = srcRGB * t;

        glowSrc *= 1.0;

        amzOutput = float4(glowSrc, src4.a);
        return;
      }


      if (amzPass == 1) {

        float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
        float kernelSize = r1 * 0.5 * (taps/10.0); 
        amzOutput = blurInternal(1, to, uv, kernelSize);
        return;
      }
      if (amzPass == 2) {

        float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
        float kernelSize = r1 * 0.5 * (taps/10.0);
        amzOutput = blurInternal(2, to, uv, kernelSize);
        return;
      }
      if (amzPass == 3) {

        float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
        float kernelSize = r2 * 0.5 * (taps/10.0);
        amzOutput = blurInternal(1, to, uv, kernelSize);
        return;
      }
      if (amzPass == 4) {

        float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
        float kernelSize = r2 * 0.5 * (taps/10.0);
        amzOutput = blurInternal(4, to, uv, kernelSize);
        return;
      }
      if (amzPass == 5) {

        float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
        float kernelSize = r3 * 0.5 * (taps/10.0);
        amzOutput = blurInternal(1, to, uv, kernelSize);
        return;
      }
      if (amzPass == 6) {

        float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
        float kernelSize = r3 * 0.5 * (taps/10.0);
        amzOutput = blurInternal(6, to, uv, kernelSize);
        return;
      }




      float4 src = amzTexture(0, uv);
      float3 b1 = amzTexture(3, uv).rgb;
      float3 b2 = amzTexture(5, uv).rgb;
      float4 b3s = amzTexture(7, uv);
      float3 b3 = b3s.rgb;


      float w2 = 0.6 * amzp_glowTail;
      float w3 = 0.3 * amzp_glowTail;
      float3 glowLin = srgbToLinear(b1) + srgbToLinear(b2) * w2 + srgbToLinear(b3) * w3;
      glowLin *= max(amzp_exposure, 0.0);
      glowLin = 1.0 - exp(-glowLin * amzp_softClipKnee);
      float3 glowBase = linearToSrgb(glowLin);
      float3 glow = mix(glowBase, glowBase * amzp_tint.rgb, clamp(amzp_tintStrength, 0.0, 1.0));
      float glowA = clamp(b3s.a * amzp_glowOcclusion, 0.0, 1.0);


      float4 base = src;


      if ((amzp_sshadow>0.5)) {
        float2 imgSize = getTexSize((screen.zw/1.0));
        float px = (1.0/imgSize.x);
        float py = (1.0/imgSize.y);
        float ang = radians(amzp_direction);
        float2 offs = float2(cos(ang), sin(ang)) * amzp_distance;
        float2 shadowUV = uv + offs * float2(px, py);

        float sscale = max(amzp_softness, 1.0);
        float2 amzp_spread = float2(px, py) * sscale * 0.5;

        float a0 = amzTexture(7, shadowUV).a;
        float a1 = amzTexture(7, shadowUV + float2(amzp_spread.x, 0.0)).a;
        float a2 = amzTexture(7, shadowUV - float2(amzp_spread.x, 0.0)).a;
        float a3 = amzTexture(7, shadowUV + float2(0.0, amzp_spread.y)).a;
        float a4 = amzTexture(7, shadowUV - float2(0.0, amzp_spread.y)).a;
        float a5 = amzTexture(7, shadowUV + float2(amzp_spread.x, amzp_spread.y)).a;
        float a6 = amzTexture(7, shadowUV + float2(-amzp_spread.x, amzp_spread.y)).a;
        float a7 = amzTexture(7, shadowUV + float2(amzp_spread.x, -amzp_spread.y)).a;
        float a8 = amzTexture(7, shadowUV + float2(-amzp_spread.x, -amzp_spread.y)).a;
        float shadowA = (a0 + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8) / 9.0;
        shadowA = clamp(shadowA * 1.8, 0.0, 1.0);
        shadowA = 1.0 - pow(max(0.0, 1.0 - shadowA), 0.45);

        float alphaEff = clamp(amzp_shadowAlpha * amzp_alphaa, 0.0, 1.0);
        float4 outColor = float4(amzp_shadowColor.rgb, clamp(shadowA * alphaEff, 0.0, 1.0));

        if ((amzp_shadowOnly>0.5)) {
          amzOutput = outColor;
          return;
        }

        float behindMask = 1.0 - step(0.001, base.a);
        base = base + outColor * behindMask;
      }


      float3 srcLin = srgbToLinear(base.rgb);
      float3 compLin;
      float bmf = float(int(amzp_blendMode));
      if (bmf < 1.5) {
        compLin = srcLin + srgbToLinear(glow);
      } else if (bmf < 2.5) {
        float3 compS = 1.0 - (1.0 - base.rgb) * (1.0 - clamp(glow, 0.0, 100.0));
        compLin = srgbToLinear(compS);
      } else {
        compLin = max(srcLin, srgbToLinear(glow));
      }
      float3 finalColor = linearToSrgb(compLin);
      float2 imgPx = getTexSize((screen.zw/1.0)) * uv;
      float2 ip = floor(imgPx);
      float n1 = fract(sin(dot(ip, float2(12.9898,78.233))) * 43758.5453);
      float n2 = fract(sin(dot(ip, float2(24.1230,17.3210))) * 12345.6789);
      float n3 = fract(sin(dot(ip, float2(93.9890,67.3450))) * 98765.4321);
      float3 dn = float3(n1, n2, n3) - 0.5;
      finalColor = clamp(finalColor + dn * amzp_ditherAmount, 0.0, 1.0);

      if ((amzp_glowOnly>0.5)) {
        finalColor = glow;
        amzOutput = float4(finalColor, glowA);
        return;
      }

      float finalAlpha = clamp(base.a + glowA, 0.0, 1.0);
      amzOutput = float4(finalColor, finalAlpha);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

